class SimpleBookDao {
  private final Connection conn;
  SimpleBookDao(Connection conn) { this.conn = conn; }
  void insert(String title, String author) throws SQLException {
    try (PreparedStatement ps = conn.prepareStatement("INSERT INTO books (title, author) VALUES (?,?)")) {
      ps.setString(1, title); ps.setString(2, author); ps.executeUpdate();
    }
  }
}

boolean existsByTitle(String title) throws SQLException {
  try (PreparedStatement ps = conn.prepareStatement("SELECT COUNT(*) FROM books WHERE title=?")) {
    ps.setString(1, title);
    try (ResultSet rs = ps.executeQuery()) { rs.next(); return rs.getInt(1) > 0; }
  }
}
