static boolean hasMinLength(String s, int min) { return s.length() >= min; }
static boolean hasDigit(String s) { return s.chars().anyMatch(Character::isDigit); }
static boolean hasUpperCase(String s) { return s.chars().anyMatch(Character::isUpperCase); }
static void registerAccount(AccountDao dao, String username, String password) throws SQLException {
  if (!hasMinLength(password, 8)) { System.out.println("Za krotkie haslo"); return; }
  if (!hasDigit(password)) { System.out.println("Brak cyfry"); return; }
  if (!hasUpperCase(password)) { System.out.println("Brak wielkiej litery"); return; }
  dao.insert(username, password);
}

